ax to 0.\n                \n                if (u == num_nodes - 1 && v == num_nodes - 1 && path_type == 0 && d == num_nodes) begin\n                    // This is the last configuration (u=max, v=max, path=direct, d=no_device)\n                    // Wait, we iterate d from 0..num_nodes. \n                    // So last config is u=max, v=max, path=2-hop, h=max, d=num_nodes? \n                    // No, h wraps, d wraps, path wraps, v wraps, u wraps.\n                    // Let's track 'done' via a flag or check.\n                    // Actually, simply: if we are at the state where the NEXT increment wraps u to 0.\n                    // The next increment logic calculates next state.\n                    // If we are at the state just before wrapping u:\n                    // u = num_nodes - 1\n                    // v = num_nodes - 1\n                    // path_type = 1\n                    // d = num_nodes\n                    // h = num_nodes - 1\n                    // This is the absolute last configuration.\n                    if (u == num_nodes - 1 && v == num_nodes - 1 && path_type == 2'd1 && d == num_nodes && h == num_nodes - 1) begin\n                        // After this, we will increment h -> no (wrap), d -> 0 (wrap), path -> 0 (wrap), v -> 0 (wrap), u -> 0 (wrap)\n                        // Wait. if d == num_nodes, it wraps to 0. path_type wraps to 0. v wraps to 0. u wraps to 0.\n                        // We need to detect when u wraps from num_nodes-1 to 0.\n                        // In COMPARE block, we update u.\n                        // If u is currently num_nodes - 1, and we determine we must increment u (because all others wrapped),\n                        // then u becomes 0. We should set done then.\n                        // \n                        // Let's modify the increment logic to set 'done' when u wraps.\n                    end\n                end\n            end\n        end\n    end\n\n    // Revised Increment Logic with Done detection\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // handled\n        end else if (state == COMPARE) begin\n            // We perform the increment and check for overflow (cycle complete)\n            \n            // 1. h\n            if (path_type == 2'd1 && h < num_nodes - 1) begin\n                h <= h + 4'd1;\n            end else begin\n                // h done, wrap\n                h <= 4'd0;\n                \n                // 2. d\n                if (d < num_nodes) begin\n                    d <= d + 4'd1;\n                end else begin\n                    // d done, wrap\n                    d <= 4'd0;\n                    \n                    // 3. path_type\n                    if (path_type == 2'd0) begin\n                        path_type <= 2'd1;\n                    end else begin\n                        // path_type done, wrap\n                        path_type <= 2'd0;\n                        \n                        // 4. v\n                        if (v < num_nodes - 1) begin\n                            v <= v + 4'd1;\n                        end else begin\n                            // v done, wrap\n                            v <= 4'd0;\n                            \n                            // 5. u\n                            if (u < num_nodes - 1) begin\n                                u <= u + 4'd1;\n                            end else begin\n                                // u done, cycle complete\n                                // We should go to FINISH\n                                // We need to signal this to the FSM.\n                                // Since we are inside a clocked block, we can set a flag or force state.\n                                // But state transition is handled in combinational logic.\n                                // We can set u to 0 (it already wraps) and let FSM see it.\n                                // However, we need to ensure we don't loop forever.\n                                // We can set a 'finished' flag.\n                                \n                                // To be safe, let's set u to 0 and trust the FSM combinational logic.\n                                // But we need to make sure we don't immediately restart.\n                                // The FSM will go SETUP -> COMPARE -> SETUP.\n                                // In SETUP, if indices are invalid (e.g. u=0, v=0, types[0]!=1), it will go COMPARE again.\n                                // This might be okay, but eventually we need to stop.\n                                // \n                                // Better: Check if this is the LAST valid configuration to calculate.\n                                // But we don't know if the last config is valid.\n                                // \n                                // Approach: \n                                // If u wraps (u was num_nodes-1, now 0), set a flag 'all_visited' or set state to FINISH directly.\n                                \n                                // We can't easily change state from inside this block if combinational logic overrides it.\n                                // But we can set a 'finish_flag'.\n                                // \n                                // Let's use a register 'done_flag'.\n                                // If (u == num_nodes-1 && v == num_nodes-1 && path_type==1 && d==num_nodes && h==num_nodes-1)\n                                // then next cycle we are done.\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n\n    // Add finish flag detection\n    reg cycle_done;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            cycle_done <= 1'b0;\n        end else begin\n            // We are at the beginning of COMPARE state.\n            // We are about to increment.\n            // Check if this is the last configuration in the sequence.\n            // The sequence ends when u=num_nodes-1, v=num_nodes-1, path=2-hop, d=num_nodes, h=num_nodes-1.\n            // Actually, the sequence includes all d. \n            // The last iteration of the loop is u=max, v=max, path=2-hop, d=num_nodes, h=max.\n            // Wait, path=2-hop includes h. path=direct doesn't.\n            // The loop order is: u -> v -> d -> path -> h.\n            // So the "last" state before wrap is:\n            // u = num_nodes - 1\n            // v = num_nodes - 1\n            // d = num_nodes\n            // path_type = 1\n            // h = num_nodes - 1\n            // When we are in this state, we increment h (wrap), d (wrap), path (wrap), v (wrap), u (wrap).\n            // \n            // So if we are in COMPARE and:\n            if (state == COMPARE && !cycle_done) begin\n                if (u == num_nodes - 1 && v == num_nodes - 1 && d == num_nodes && path_type == 2'd1 && h == num_nodes - 1) begin\n                    // This is the last config. \n                    // After this, we cycle to u=0, etc.\n                    // We should set cycle_done.\n                    // And force state to FINISH next cycle? \n                    // No, let's just set cycle_done and in the FSM, if cycle_done and state == SETUP (or COMPARE), go to FINISH.\n                    // But indices will be reset. \n                    // \n                    // Actually, the logic above will reset indices to 0 in COMPARE block.\n                    // So if we are in this "last" state, the increment block will reset indices to 0.\n                    // This effectively restarts the loop. \n                    // We need to prevent the restart.\n                    // \n                    // So, in the increment block, if we detect this condition, we should NOT update indices.\n                    // Instead, we set cycle_done = 1.\n                    // And maybe set indices to a known state (0) just for cleanliness.\n                    // \n                    // Let's refine the increment block to check cycle_done first.\n                    cycle_done <= 1'b1;\n                    u <= 4'd0; // Reset for next time? Or just leave.\n                end\n            end\n            \n            if (start) cycle_done <= 1'b0;\n        end\n    end\n\n    // Final FSM with cycle_done\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: if (start) next_state = SETUP;\n            SETUP: begin\n                if (cycle_done) next_state = FINISH;\n                else if (is_valid_path()) next_state = CALCULATE;\n                else next_state = COMPARE;\n            end\n            CALCULATE: next_state = ACCUMULATE;\n            ACCUMULATE: next_state = COMPARE;\n            COMPARE: begin\n                if (cycle_done) next_state = FINISH;\n                else next_state = SETUP;\n            end\n            FINISH: next_state = FINISH;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // Helper function for validity check (combinational)\n    function is_valid_path;\n        reg valid;\n        begin\n            valid = 1'b0;\n            if (u < num_nodes && v < num_nodes && u != v && \n                types[u] == 1'b1 && types[v] == 1'b0) begin\n                \n                if (path_type == 2'd0) begin\n                    if (adj_matrix[(u * 16) + v]) valid = 1'b1;\n                end else if (path_type == 2'd1) begin\n                    if (h < num_nodes && h != u && h != v && \n                        adj_matrix[(u * 16) + h] && adj_matrix[(h * 16) + v]) begin\n                        valid = 1'b1;\n                    end\n                end\n            end\n            is_valid_path = valid;\n        end\n    endfunction\n\n    // Fix for increment logic to respect cycle_done\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // reset\n        end else if (state == COMPARE && !cycle_done) begin\n            // Perform increment\n            if (path_type == 2'd1 && h < num_nodes - 1) begin\n                h <= h + 4'd1;\n            end else begin\n                h <= 4'd0;\n                if (d < num_nodes) begin\n                    d <= d + 4'd1;\n                end else begin\n                    d <= 4'd0;\n                    if (path_type == 2'd0) begin\n                        path_type <= 2'd1;\n                    end else begin\n                        path_type <= 2'd0;\n                        if (v < num_nodes - 1) begin\n                            v <= v + 4'd1;\n                        end else begin\n                            v <= 4'd0;\n                            if (u < num_nodes - 1) begin\n                                u <= u + 4'd1;\n                            end else begin\n                                // u wraps to 0, this triggers cycle_done in next cycle check\n                                // But we must ensure we don't keep looping here.\n                                // Since this is inside COMPARE block and cycle_done is not yet set,\n                                // we will increment u to 0.\n                                // The check in the sequential block above (cycle_done <= 1'b1) \n                                // relies on u being num_nodes-1.\n                                // So we need to update u here, then check.\n                                u <= 4'd0;\n                                // Note: cycle_done will be set in the same cycle (if we add the logic here) or next.\n                                // The logic above checks u == num_nodes-1. \n                                // If we are executing this line, u WAS num_nodes-1.\n                                // So we should set cycle_done here.\n                                // But we are in an always block. \n                                // We can't set cycle_done here if it's defined in another always block (though technically allowed, it's bad practice).\n                                // Let's move the cycle_done logic here.\n                            end\n                        end\n                    end\n                end\n            end\n            \n            // Check for completion immediately after increment logic\n            // Actually, checking BEFORE increment is easier to detect the "last" state.\n            // But checking AFTER increment handles the wrap.\n            // We need to detect when we just passed the last state.\n            // If u was num_nodes-1, v was max, etc., then we just finished.\n            // So if u == num_nodes-1 && v == num_nodes-1 && ... then cycle_done = 1.\n            // \n            // However, we just updated u to 0 in the else branch. \n            // So we can't check u == num_nodes-1 now.\n            // We should check BEFORE updating.\n        end\n    end\n\n    // Corrected Increment with Cycle Done detection\n    // We need a separate combinational block to determine 'increment_action'\n    // or do it purely sequentially with look-back.\n    // Sequential look-back is safer.\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            cycle_done <= 1'b0;\n        end else if (state == COMPARE) begin\n            if (!cycle_done) begin\n                // Check if we are at the very end of the search space\n                // If u == num_nodes-1, v == num_nodes-1, path_type == 1, d == num_nodes, h == num_nodes-1\n                if (u == num_nodes - 1 && v == num_nodes - 1 && path_type == 2'd1 && d == num_nodes && h == num_nodes - 1) begin\n                    cycle_done <= 1'b1;\n                    // Do not increment indices, stay at 0 or invalid\n                end else begin\n                    // Perform increment\n                    if (path_type == 2'd1 && h < num_nodes - 1) begin\n                        h <= h + 4'd1;\n                    end else begin\n                        h <= 4'd0;\n                        if (d < num_nodes) begin\n                            d <= d + 4'd1;\n                        end else begin\n                            d <= 4'd0;\n                            if (path_type == 2'd0) begin\n                                path_type <= 2'd1;\n                            end else begin\n                                path_type <= 2'd0;\n                                if (v < num_nodes - 1) begin\n                                    v <= v + 4'd1;\n                                end else begin\n                                    v <= 4'd0;\n                                    if (u < num_nodes - 1) begin\n                                        u <= u + 4'd1;\n                                    end else begin\n                                        // This should ideally not be reached if the 'if' condition above catches it\n                                        // But if u was num_nodes-1 and we are here, it means the check failed?\n                                        // No, if u == num_nodes-1, we take the cycle_done path.\n                                    end\n                                end\n                            end\n                        end\n                    end\n                end\n            end\n        end\n        \n        if (start) cycle_done <= 1'b0;\n    end\n\nendmodule\n"
